INSERT INTO `animals` VALUES (1,'Gallus gallus domesticus','Кобб 500','Птахи','Gallus','Phasianidae','35-45 см','2.50','6','Ферми, сільська місцевість','Всеїдні','Швидке зростання, низьке споживання корму','Просторі загони, температура 20-25°C','Інкубатори або природним шляхом','М\'ясо','https://example.com/cobb500.jpg','Кобб 500 відомі швидким зростанням і високою м\'ясною продуктивністю.'),(2,'Gallus gallus domesticus','Росс 308','Птахи','Gallus','Phasianidae','35-45 см','2.60','6','Ферми, сільська місцевість','Всеїдні','Стійкість до хвороб, високий вихід філе','Просторі загони, температура 20-25°C','Інкубатори або природним шляхом','М\'ясо','https://example.com/ross308.jpg','Росс 308 популярні завдяки високій м\'ясній продуктивності та швидкому набору ваги.'),(3,'Gallus gallus domesticus','Плімутрок','Птахи','Gallus','Phasianidae','50-60 см','3.50','8','Ферми, подвір’я, сільська місцевість','Всеїдні','Універсальна порода: висока м\'ясна і яєчна продуктивність','Просторі загони, регулярне чищення та вентиляція приміщень','Природним шляхом або інкубаторами','М\'ясо, яйця, декоративне використання','https://example.com/plymouthrock.jpg','Плімутрок — популярна універсальна порода, яка забезпечує високу продуктивність як м’яса, так і яєць. Відома своєю витривалістю та невибагливістю.'),(4,'Gallus gallus domesticus','Орловська ситцева','Птахи','Gallus','Phasianidae','50-70 см','3.00','7','Ферми, подвір’я, сільська місцевість','Всеїдні','Витривалі, декоративний окрас, пристосовані до холодного клімату','Зимостійкість, просторі загони з гарною вентиляцією','Природним шляхом','М\'ясо, декоративне використання, яйця','https://example.com/orlovskaya.jpg','Кури починають нестися в 7-8 місяців. У перший рік життя вони можуть знести до 180 яєць, далі продуктивність знижується до 150. Яйця важать 60 г.'),(5,'Gallus gallus domesticus','Фавероль','Птахи','Gallus','Phasianidae','50-60 см','3.50','7','Ферми, подвір’я, сільська місцевість','Всеїдні','М\'ясна та яєчна продуктивність, декоративне оперення','Просторі загони, необхідність гарної вентиляції','Природним шляхом','М\'ясо, декоративне використання, яйця','https://example.com/faverolles.jpg','Курочки можуть дати близько 150 яєць на рік'),(6,'Gallus gallus domesticus','Орпінгтон','Птахи','Gallus','Phasianidae','55-70 см','4.50','8','Ферми, подвір’я, сільська місцевість','Всеїдні','М’ясо-яєчна порода, спокійний темперамент','Просторі загони, хороший захист від холоду','Інкубатори або природним шляхом','М’ясо, яйця','https://example.com/orpington.jpg','У середньому 180 яєць на рік'),(7,'Gallus gallus domesticus','Кучинські Ювілейні','Птахи','Gallus','Phasianidae','50 см','3.00','7','Ферми, подвір’я, сільська місцевість','Всеїдні','Висока продуктивність яєць, декоративний вигляд','Просторі загони, доступ до свіжої води','Природним шляхом або інкубаторами','Яйця, декоративне використання','https://example.com/kuchinskij.jpg','Дають у середньому 180 яєць на рік. Яйця середнього розміру кремового кольору.'),(8,'Gallus gallus domesticus','Кохінхін','Птахи','Gallus','Phasianidae','70 см','5.00','8','Ферми, подвір’я, сільська місцевість','Всеїдні','Великі кури, високий рівень м’ясної продуктивності','Просторі загони, утримання в теплому кліматі','Природним шляхом','М’ясо, декоративне використання','https://example.com/cochin.jpg','Дає до 120 яєць на рік (вага яйця в середньому 55 г)'),(9,'Gallus gallus domesticus','Брама','Птахи','Gallus','Phasianidae','60-70 см','4.50','8','Ферми, подвір’я, сільська місцевість','Всеїдні','М’ясо-яєчні кури, вражаючий розмір і вага','Просторі загони, температурні умови 15-25°C','Інкубатори або природним шляхом','М’ясо, яйця','https://example.com/brahma.jpg','При вазі тіла в 3 кг курка може принести 100-120 яєць в рік. Середня вага кожного яйця становить 50-65 г.'),(10,'Gallus gallus domesticus','Корніш','Птахи','Gallus','Phasianidae','55-60 см','3.80','7','Ферми, подвір’я, сільська місцевість','Всеїдні','Порода м’ясного напрямку, сильна мускулатура','Просторі заго